/* --- the generated ambient bed ----------------------------------------
** Two instruments - a primary that arpeggiates, a secondary that sustains
** - each with four banks.  Every step is a CHORD DEGREE rather than a
** pitch, so both voices can only ever name notes that are in the bar's
** chord, and no pairing of banks can be dissonant. */
#define BANKS           4
#define BANK_MAX_STEPS  8

struct bank {
    unsigned char len;                      /* steps in the figure  */
    unsigned char step[BANK_MAX_STEPS];     /* chord-tone indices   */
    unsigned char oct;                      /* semitones added      */
    unsigned char div;                      /* ticks per arp step   */
};

static const struct bank primary[BANKS] = {
    { 3, {0,1,2,0,0,0,0,0},  0,  7 },
    { 4, {0,2,1,3,0,0,0,0},  0,  5 },
    { 6, {0,1,2,3,2,1,0,0},  0,  3 },
    { 2, {0,3,0,0,0,0,0,0},  0, 11 },
};

/* Two degrees each: a secondary bank alternates between them bar by
** bar, which is how a hurdy-gurdy's two drone strings behave. */
static const unsigned char secondary[BANKS][2] = {
    { 0, 0 },
    { 0, 2 },
    { 2, 2 },
    { 1, 0 },
};

#define PROGRESSION_BARS 8
static const unsigned char progression[PROGRESSION_BARS] = {
    0, 10, 5, 7, 0, 10, 3, 7
};

/* Phrases each instrument holds a bank for.  Coprime rates are the
** point: 1 against 3 takes 12 phrases to pair the same two banks
** twice, which is the bed's longest structure. */
#define PRIM_EVERY      1
#define SEC_EVERY       3

